{"source":"#include <stdio.h>

int main(int argc, char *argv[])
{
int a,b; scanf("%d %d",&a,&b);
int n;
if(a<b){
printf("-1");
return -1;
}
if(a==b){
printf("%.10lf",(double)b);
return 0;
}

n=a/b;
if(n%2==0)
--n;

double x=(double)a/((double)a/((double)a/((double)b + (double)a)*(n+1)));
printf("%.12lf\n",x);

return 0;
}"}
